import{_ as l,a0 as d,w as o,s as r,ao as p,I as n,x as i,a1 as s,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 新手必知必会的 10 条 Linux 基本命令 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember","title":"Linux 新手必知必会的 10 条 Linux 基本命令","tag":"201607","desc":""},"relativePath":"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember.md","filePath":"[post].md"}'),h={name:"201607/20160616 10 Basic Linux Commands That Every Linux Newbies Should Remember.md"};function u(c,e,g,b,k,m){const a=d("Link");return o(),r("div",null,[e[13]||(e[13]=p(`<h1 id="linux-新手必知必会的-10-条-linux-基本命令" tabindex="-1">Linux 新手必知必会的 10 条 Linux 基本命令 <a class="header-anchor" href="#linux-新手必知必会的-10-条-linux-基本命令" aria-label="Permalink to “Linux 新手必知必会的 10 条 Linux 基本命令”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/4225072_orig.png" alt=""></p><p>Linux 对我们的生活产生了巨大的冲击。至少你的安卓手机使用的就是 Linux 核心。尽管如此，在第一次开始使用 Linux 时你还是会感到难以下手。因为在 Linux 中，通常需要使用终端命令来取代 Windows 系统中的点击启动图标操作。但是不必担心，这里我们会介绍 10 个 Linux 基本命令来帮助你开启 Linux 神秘之旅。</p><h3 id="帮助新手走出第一步的-10-个-linux-基本命令" tabindex="-1">帮助新手走出第一步的 10 个 Linux 基本命令 <a class="header-anchor" href="#帮助新手走出第一步的-10-个-linux-基本命令" aria-label="Permalink to “帮助新手走出第一步的 10 个 Linux 基本命令”">​</a></h3><p>当我们谈论 Linux 命令时，实质上是在谈论 Linux 系统本身。这短短的 10 个 Linux 基本命令不会让你变成天才或者 Linux 专家，但是能帮助你轻松开始 Linux 之旅。使用这些基本命令会帮助新手们完成 Linux 的日常任务，由于它们的使用频率如此至高，所以我更乐意称他们为 Linux 命令之王！</p><p>让我们开始学习这 10 条 Linux 基本命令吧。</p><h4 id="_1-sudo" tabindex="-1">1. sudo <a class="header-anchor" href="#_1-sudo" aria-label="Permalink to “1. sudo”">​</a></h4><p>这条命令的意思是“以超级用户的身份执行”，是 SuperUserDo 的简写，它是新手将要用到的最重要的一条 Linux 命令。当一条单行命令需要 root 权限的时候，<code>sudo</code>命令就派上用场了。你可以在每一条需要 root 权限的命令前都加上<code>sudo</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su</span></span></code></pre></div><h4 id="_2-ls-list" tabindex="-1">2. ls (list) <a class="header-anchor" href="#_2-ls-list" aria-label="Permalink to “2. ls (list)”">​</a></h4><p>跟其他人一样，你肯定也经常想看看目录下都有些什么东西。使用列表命令，终端会把当前工作目录下所有的文件以及文件夹展示给你。比如说，我当前处在 /home 文件夹中，我想看看 /home 文件夹中都有哪些文件和目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home$ ls</span></span></code></pre></div><p>在 /home 中执行<code>ls</code>命令将会返回类似下面的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>imad lost+found</span></span></code></pre></div><h4 id="_3-cd" tabindex="-1">3. cd <a class="header-anchor" href="#_3-cd" aria-label="Permalink to “3. cd”">​</a></h4><p>变更目录命令（cd）是终端中总会被用到的主要命令。它是最常用到的 Linux 基本命令之一。此命令使用非常简单，当你打算从当前目录跳转至某个文件夹时，只需要将文件夹键入此命令之后即可。如果你想跳转至上层目录，只需要在此命令之后键入两个点 (..) 就可以了。 ​ 举个例子，我现在处在 /home 目录中，我想移动到 /home 目录中的 usr 文件夹下，可以通过以下命令来完成操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home $ cd usr</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/home/usr $</span></span></code></pre></div><h4 id="_4-mkdir" tabindex="-1">4. mkdir <a class="header-anchor" href="#_4-mkdir" aria-label="Permalink to “4. mkdir”">​</a></h4><p>只是可以切换目录还是不够完美。有时候你会想要新建一个文件夹或子文件夹。此时可以使用 mkdir 命令来完成操作。使用方法很简单，只需要把新的文件夹名跟在 mkdir 命令之后就好了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~$ mkdir folderName</span></span></code></pre></div><h4 id="_5-cp" tabindex="-1">5. cp <a class="header-anchor" href="#_5-cp" aria-label="Permalink to “5. cp”">​</a></h4><p>拷贝-粘贴（copy-and-paste）是我们组织文件需要用到的重要命令。使用 <code>cp</code> 命令可以帮助你在终端当中完成拷贝-粘贴操作。首先确定你想要拷贝的文件，然后键入打算粘贴此文件的目标位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp src des</span></span></code></pre></div><p>注意：如果目标目录对新建文件需要 root 权限时，你可以使用 <code>sudo</code> 命令来完成文件拷贝操作。</p><h4 id="_6-rm" tabindex="-1">6. rm <a class="header-anchor" href="#_6-rm" aria-label="Permalink to “6. rm”">​</a></h4><p>rm 命令可以帮助你移除文件甚至目录。如果不希望每删除一个文件都提示确认一次，可以用<code>-f</code>参数来强制执行。也可以使用 <code>-r</code> 参数来递归的移除文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm myfile.txt</span></span></code></pre></div><h4 id="_7-apt-get" tabindex="-1">7. apt-get <a class="header-anchor" href="#_7-apt-get" aria-label="Permalink to “7. apt-get”">​</a></h4><p>这个命令会依据发行版的不同而有所区别。在基于 Debian 的发行版中，我们拥有 Advanced Packaging Tool（APT）包管理工具来安装、移除和升级包。apt-get 命令会帮助你安装需要在 Linux 系统中运行的软件。它是一个功能强大的命令行，可以用来帮助你对软件执行安装、升级和移除操作。</p><p>在其他发行版中，例如 Fedora、Centos，都各自不同的包管理工具。Fedora 之前使用的是 yum，不过现在 dnf 成了它默认的包管理工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo dnf update</span></span></code></pre></div><h4 id="_8-grep" tabindex="-1">8. grep <a class="header-anchor" href="#_8-grep" aria-label="Permalink to “8. grep”">​</a></h4><p>当你需要查找一个文件，但是又忘记了它具体的位置和路径时，<code>grep</code> 命令会帮助你解决这个难题。你可以提供文件的关键字，使用<code>grep</code>命令来查找到它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep user /etc/passwd</span></span></code></pre></div><h4 id="_9-cat" tabindex="-1">9. cat <a class="header-anchor" href="#_9-cat" aria-label="Permalink to “9. cat”">​</a></h4><p>作为一个用户，你应该会经常需要浏览脚本内的文本或者代码。<code>cat</code>命令是 Linux 系统的基本命令之一，它的用途就是将文件的内容展示给你。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat CMakeLists.txt</span></span></code></pre></div><h4 id="_10-poweroff" tabindex="-1">10. poweroff <a class="header-anchor" href="#_10-poweroff" aria-label="Permalink to “10. poweroff”">​</a></h4><p>最后一个命令是 <code>poweroff</code>。有时你需要直接在终端中执行关机操作。此命令可以完成这个任务。由于关机操作需要 root 权限，所以别忘了在此命令之前添加<code>sudo</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo poweroff</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如我在文章开始所言，这 10 条命令并不会让你立即成为一个 Linux 大拿，但它们会让你在初期快速上手 Linux。以这些命令为基础，给自己设置一个目标，每天学习一到三条命令，这就是此文的目的所在。在下方评论区分享有趣并且有用的命令。别忘了跟你的朋友分享此文。</p><hr>`,43)),n("p",null,[e[1]||(e[1]=i("via: ",-1)),s(a,{href:"http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember"},{default:t(()=>[...e[0]||(e[0]=[i("http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=i("作者：",-1)),s(a,{href:"http://www.linuxandubuntu.com/home/10-basic-linux-commands-that-every-linux-newbies-should-remember#comments"},{default:t(()=>[...e[2]||(e[2]=[i("Commenti",-1)])]),_:1}),e[6]||(e[6]=i(" 译者：",-1)),s(a,{href:"https://github.com/mr-ping"},{default:t(()=>[...e[3]||(e[3]=[i("mr-ping",-1)])]),_:1}),e[7]||(e[7]=i(" 校对：",-1)),s(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=i("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原创编译，",-1)),s(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[i("Linux中国",-1)])]),_:1}),e[12]||(e[12]=i(" 荣誉推出",-1))])])}const y=l(h,[["render",u]]);export{L as __pageData,y as default};
